import itertools
import numpy as np
import numba as nb

@nb.njit(fastmath=True)
def homotopy_nb(x0, A, k, alpha, maxev):
    m, d = A.shape
    z = A @ x0
    # top-k
    order = np.argsort(-z)
    state = np.zeros(m, np.int8)
    for i in range(k):
        state[order[i]] = 1
    f0 = 0.0
    for i in range(k):
        f0 += z[order[i]]
    if f0 <= alpha:
        return x0.copy(), 0, state, 0.0
    aT = np.zeros(d)
    for i in range(k):
        aT += A[order[i]]
    nT = k
    Elist = np.empty(d + 2, np.int64)
    e = 0
    G = np.zeros((d + 2, d + 2))
    wE = np.zeros(d + 2)
    mu = 0.0
    t = 0.0
    zq = np.empty(m)
    xq = np.empty(d)
    nev = 0
    while nev < maxev:
        nev += 1
        if e == 0:
            # xq = -aT
            for j in range(d):
                xq[j] = -aT[j]
            for i in range(m):
                s = 0.0
                for j in range(d):
                    s += A[i, j] * xq[j]
                zq[i] = s
            f = 0.0; fq = 0.0
            for i in range(m):
                if state[i] == 1:
                    f += z[i]; fq += zq[i]
            sstop = (alpha - f) / fq
            best = sstop; bi = -1; bj = -1
            for i in range(m):
                if state[i] != 1:
                    continue
                for j in range(m):
                    if state[j] != 0:
                        continue
                    dq = zq[j] - zq[i]
                    if dq > 0:
                        s = (z[i] - z[j]) / dq
                        if s < best:
                            best = s; bi = i; bj = j
            for i in range(m):
                z[i] += best * zq[i]
            mu += best
            if bi < 0:
                return x0 - mu * aT, nev, state, mu
            t = 0.5 * (z[bi] + z[bj])
            state[bi] = 2; state[bj] = 2
            aT -= A[bi]
            nT -= 1
            # add bi, bj to E
            for newi in (bi, bj):
                for p in range(e):
                    q = Elist[p]
                    s = 0.0
                    for j in range(d):
                        s += A[q, j] * A[newi, j]
                    G[p, e] = s; G[e, p] = s
                s = 0.0
                for j in range(d):
                    s += A[newi, j] * A[newi, j]
                G[e, e] = s
                Elist[e] = newi
                e += 1
            wE[0] = mu; wE[1] = 0.0
            continue
        # bordered system
        n = e + 1
        M = np.empty((n, n))
        rhs = np.empty(n)
        for p in range(e):
            for q in range(e):
                M[p, q] = G[p, q]
            M[p, e] = 1.0; M[e, p] = 1.0
            r = Elist[p]
            s = 0.0
            for j in range(d):
                s += A[r, j] * aT[j]
            rhs[p] = -s
        M[e, e] = 0.0
        rhs[e] = k - nT
        sol = np.linalg.solve(M, rhs)
        tq = sol[e]
        for j in range(d):
            xq[j] = -aT[j]
        for p in range(e):
            r = Elist[p]
            wp = sol[p]
            for j in range(d):
                xq[j] -= wp * A[r, j]
        for i in range(m):
            s = 0.0
            for j in range(d):
                s += A[i, j] * xq[j]
            zq[i] = s
        f = (k - nT) * t; fq = (k - nT) * tq
        for i in range(m):
            if state[i] == 1:
                f += z[i]; fq += zq[i]
        best = np.inf; kind = 0; who = -1
        if fq < 0:
            best = (alpha - f) / fq
        for p in range(e):
            wq = sol[p]
            if wq < 0:
                s = -wE[p] / wq
                if s < best:
                    best = s; kind = 1; who = p
            if wq > 1:
                s = (mu - wE[p]) / (wq - 1)
                if s < best:
                    best = s; kind = 2; who = p
        for i in range(m):
            st = state[i]
            if st == 2:
                continue
            dz = z[i] - t
            dq = zq[i] - tq
            if st == 1:
                if dq < 0:
                    s = -dz / dq
                    if s < best:
                        best = s; kind = 3; who = i
            else:
                if dq > 0:
                    s = -dz / dq
                    if s < best:
                        best = s; kind = 3; who = i
        if best < 0:
            best = 0.0
        # advance
        for i in range(m):
            z[i] += best * zq[i]
        t += best * tq
        mu += best
        for p in range(e):
            wE[p] += best * sol[p]
        if kind == 0:
            break
        if kind == 1 or kind == 2:
            r = Elist[who]
            if kind == 1:
                state[r] = 0
            else:
                state[r] = 1
                aT += A[r]
                nT += 1
            # remove position who: swap with last
            last = e - 1
            if who != last:
                Elist[who] = Elist[last]
                wE[who] = wE[last]
                for q in range(e):
                    G[who, q] = G[last, q]
                for q in range(e):
                    G[q, who] = G[q, last]
                G[who, who] = G[last, last]
            e -= 1
        else:
            r = who
            if state[r] == 1:
                aT -= A[r]
                nT -= 1
                wE[e] = mu
            else:
                wE[e] = 0.0
            state[r] = 2
            for p in range(e):
                q = Elist[p]
                s = 0.0
                for j in range(d):
                    s += A[q, j] * A[r, j]
                G[p, e] = s; G[e, p] = s
            s = 0.0
            for j in range(d):
                s += A[r, j] * A[r, j]
            G[e, e] = s
            Elist[e] = r
            e += 1
    # final polish: solve full system with current partition
    n = e + 2
    M = np.zeros((n, n))
    rhs = np.zeros(n)
    AEaT = np.zeros(e)
    for p in range(e):
        r = Elist[p]
        s = 0.0; s2 = 0.0
        for j in range(d):
            s += A[r, j] * aT[j]
            s2 += A[r, j] * x0[j]
        AEaT[p] = s
        rhs[p] = s2
        for q in range(e):
            M[p, q] = G[p, q]
        M[p, e] = s
        M[p, e + 1] = 1.0
        M[e, p] = s
        M[e + 1, p] = 1.0
    M[e, e] = aT @ aT
    M[e, e + 1] = -(k - nT)
    rhs[e] = aT @ x0 - alpha
    M[e + 1, e] = -(k - nT)
    sol = np.linalg.solve(M, rhs)
    mu = sol[e]
    x = x0 - mu * aT
    for p in range(e):
        r = Elist[p]
        for j in range(d):
            x[j] -= sol[p] * A[r, j]
    return x, nev, state, mu


@nb.njit(fastmath=True)
def _matvec_T(AT, x, out):
    d, m = AT.shape
    for i in range(m):
        out[i] = 0.0
    for j in range(d):
        c = x[j]
        for i in range(m):
            out[i] += c * AT[j, i]


@nb.njit(fastmath=True)
def _mv32(AT, x, out):
    d, m = AT.shape
    for i in range(m):
        out[i] = 0.0
    j = 0
    while j + 4 <= d:
        c0 = np.float32(x[j]); c1 = np.float32(x[j+1]); c2 = np.float32(x[j+2]); c3 = np.float32(x[j+3])
        for i in range(m):
            out[i] += c0 * AT[j, i] + c1 * AT[j+1, i] + c2 * AT[j+2, i] + c3 * AT[j+3, i]
        j += 4
    while j < d:
        c = np.float32(x[j])
        for i in range(m):
            out[i] += c * AT[j, i]
        j += 1


@nb.njit(fastmath=True)
def _dot(a, b, n):
    s = 0.0
    for j in range(n):
        s += a[j] * b[j]
    return s


@nb.njit(fastmath=True)
def _chol_solve(L, e, b, y):
    # solve L L^T y = b
    for i in range(e):
        s = b[i]
        for j in range(i):
            s -= L[i, j] * y[j]
        y[i] = s / L[i, i]
    for i in range(e - 1, -1, -1):
        s = y[i]
        for j in range(i + 1, e):
            s -= L[j, i] * y[j]
        y[i] = s / L[i, i]


@nb.njit(fastmath=True)
def _chol_solve2(L, e, b1, b2, y1, y2):
    for i in range(e):
        s1 = b1[i]
        s2 = b2[i]
        for j in range(i):
            l = L[i, j]
            s1 -= l * y1[j]
            s2 -= l * y2[j]
        inv = 1.0 / L[i, i]
        y1[i] = s1 * inv
        y2[i] = s2 * inv
    for i in range(e - 1, -1, -1):
        inv = 1.0 / L[i, i]
        a1 = y1[i] * inv
        a2 = y2[i] * inv
        y1[i] = a1
        y2[i] = a2
        for j in range(i):
            l = L[i, j]
            y1[j] -= l * a1
            y2[j] -= l * a2


@nb.njit(fastmath=True)
def _chol_add(L, e, g, gamma):
    # g: new column G[0:e, e]; returns False if singular
    for i in range(e):
        s = g[i]
        for j in range(i):
            s -= L[i, j] * L[e, j]
        L[e, i] = s / L[i, i]
    s = gamma
    for j in range(e):
        s -= L[e, j] * L[e, j]
    if s <= 1e-10 * gamma:
        return False
    L[e, e] = np.sqrt(s)
    return True


@nb.njit(fastmath=True)
def _chol_del(L, e, p):
    # remove row/col p from e x e factor
    for i in range(p, e - 1):
        for j in range(i + 2):
            L[i, j] = L[i + 1, j]
    for j in range(p, e - 1):
        a = L[j, j]
        b = L[j, j + 1]
        r = np.sqrt(a * a + b * b)
        c = a / r
        s = b / r
        for i in range(j, e - 1):
            u = L[i, j]
            v = L[i, j + 1]
            L[i, j] = c * u + s * v
            L[i, j + 1] = -s * u + c * v
        L[j, j + 1] = 0.0
    for i in range(e):
        L[i, e - 1] = 0.0
        L[e - 1, i] = 0.0


