def _clarabel_solve(x0, A, k, alpha):
    import scipy.sparse as sp
    import clarabel
    m, d = A.shape
    P = sp.diags(np.r_[np.ones(d), np.zeros(1 + m)]).tocsc()
    q = np.r_[-x0, np.zeros(1 + m)]
    I = sp.identity(m, format="csc")
    top = sp.hstack([sp.csc_matrix(A), -np.ones((m, 1)), -I])
    mid = sp.hstack([sp.csc_matrix((m, d)), sp.csc_matrix((m, 1)), -I])
    bot = sp.csc_matrix(np.r_[np.zeros(d), [k], np.ones(m)][None, :])
    G = sp.vstack([top, mid, bot]).tocsc()
    h = np.r_[np.zeros(2 * m), alpha]
    settings = clarabel.DefaultSettings()
    settings.verbose = False
    solver = clarabel.DefaultSolver(P, q, G, h, [clarabel.NonnegativeConeT(2 * m + 1)], settings)
    sol = solver.solve()
    return np.array(sol.x[:d])


class Solver:
    def __init__(self):
        rng = np.random.default_rng(0)
        A = rng.standard_normal((100, 10))
        x0 = rng.standard_normal(10)
        homotopy_nb(x0, A, 5, 0.5, 5000)
        AT = np.ascontiguousarray(A.T)
        homotopy2(x0, A, AT, AT.astype(np.float32), 5, 0.5, 5000)

    def solve(self, problem, **kwargs):
        x0 = np.asarray(problem["x0"], dtype=np.float64)
        L = problem["loss_scenarios"]
        if isinstance(L, np.ndarray):
            A = np.ascontiguousarray(L, dtype=np.float64)
        else:
            m_ = len(L)
            d_ = len(L[0]) if m_ else 0
            try:
                A = np.fromiter(itertools.chain.from_iterable(L), np.float64, m_ * d_).reshape(m_, d_)
            except Exception:
                A = np.asarray(L, dtype=np.float64)
        beta = float(problem.get("beta", 0.95))
        kappa = float(problem.get("kappa", 0.1))
        m, d = A.shape
        k = int((1 - beta) * m)
        if k <= 0:
            return {"x_proj": x0.tolist()}
        alpha = kappa * k
        x = None
        try:
            AT = np.ascontiguousarray(A.T)
            x, st = homotopy2(x0, A, AT, AT.astype(np.float32), k, alpha, 20 * (m + d))
            if st < 0 or not np.all(np.isfinite(x)):
                x = None
        except Exception:
            x = None
        if x is None:
            try:
                x, nev, st, mu = homotopy_nb(x0, A, k, alpha, 20 * (m + d))
                if nev < 0 or not np.all(np.isfinite(x)):
                    x = None
            except Exception:
                x = None
        if x is None:
            x = _clarabel_solve(x0, A, k, alpha)
        f = np.sum(np.partition(A @ x, m - k)[m - k:])
        if f > alpha and alpha > 0:
            x = x * (alpha / f)
        return {"x_proj": x.tolist()}
