def _np_solve(problem):
    x0 = np.asarray(problem["x0"], dtype=np.float64).ravel()
    A = np.asarray(problem["loss_scenarios"], dtype=np.float64)
    beta = float(problem.get("beta", 0.95)); kappa = float(problem.get("kappa", 0.1))
    m, n = A.shape
    k = int((1 - beta) * m)
    alpha = kappa * k
    b = A @ x0
    idx = np.argpartition(b, m - k)[m - k:]
    fb = b[idx].sum()
    if not fb > alpha:
        return x0.tolist()
    c = A[idx].sum(0)
    xx = x0 @ x0
    r0 = xx / fb
    g = x0 - r0 * c
    Ag = b - r0 * (A @ c)
    best = None
    for bt in (0.0, 0.4):
        z = b + bt * Ag
        f = np.partition(z, m - k)[m - k:].sum()
        if not f > 0:
            continue
        x = (x0 + bt * g) * (alpha / f)
        d = np.sum((x - x0) ** 2)
        if best is None or d < best[0]:
            best = (d, x)
    return best[1].tolist()

