typedef struct { _Atomic int count; char p1[60]; _Atomic int sense; char p2[60]; } bar_t;
static bar_t BAR;
static inline void barrier(int T, int *ls){
    int s = !*ls; *ls = s;
    if (atomic_fetch_add_explicit(&BAR.count,1,memory_order_acq_rel) == T-1){
        atomic_store_explicit(&BAR.count,0,memory_order_relaxed);
        atomic_store_explicit(&BAR.sense,s,memory_order_release);
    } else {
        while (atomic_load_explicit(&BAR.sense,memory_order_acquire) != s) { __asm__ volatile("yield"); }
