    double *wp = (double*)calloc(np, sizeof(double));
    double *yp = (double*)aligned_alloc(64, sizeof(double)*np*nth);
    double sp[MAXT*PAD];
    double nrm[MAXT*PAD];
    atomic_store(&BAR.count, 0); atomic_store(&BAR.sense, 0);
    /* initial norm for row 0 */
    {
        double s = 0; for (int i = 2; i < n; i++) s += a[i]*a[i];
        nrm[0] = s; for (int t = 1; t < nth; t++) nrm[t*PAD] = 0.0;
    }
    #pragma omp parallel num_threads(nth)
    {
        int tid = omp_get_thread_num();
        int T = omp_get_num_threads();
        int ls = 0;
        double *myy = yp + (size_t)np*tid;
        for (int k = 0; k < n - 1; k++) {
            int m = n - k - 1;
            const double *x = a + k*ld;          /* row k, x[i] for i>=k+1 */
            double alpha = x[k+1];
            double ss = 0.0;
            for (int t = 0; t < T; t++) ss += nrm[t*PAD];
            double tau, beta, sc;
