                    double a3 = R3[i] - p3*wi - q3*vi;
                    R0[i]=a0; R1[i]=a1; R2[i]=a2; R3[i]=a3;
                    g0 += a0*xi; g1 += a1*xi; g2 += a2*xi; g3 += a3*xi;
                    myy[i] += a0*u0 + a1*u1 + a2*u2 + a3*u3;
                }
                g[0]+=g0; g[1]+=g1; g[2]+=g2; g[3]+=g3;
                for (int q = 0; q < 4; q++) {
