@nb.njit(fastmath=True)
def _matvec_T(AT, x, out):
    d, m = AT.shape
    for i in range(m):
        out[i] = 0.0
    for j in range(d):
        c = x[j]
        for i in range(m):
            out[i] += c * AT[j, i]


@nb.njit(fastmath=True)
def _mv32(AT, x, out):
    d, m = AT.shape
    for i in range(m):
        out[i] = 0.0
    j = 0
    while j + 4 <= d:
        c0 = np.float32(x[j]); c1 = np.float32(x[j+1]); c2 = np.float32(x[j+2]); c3 = np.float32(x[j+3])
        for i in range(m):
            out[i] += c0 * AT[j, i] + c1 * AT[j+1, i] + c2 * AT[j+2, i] + c3 * AT[j+3, i]
        j += 4
    while j < d:
        c = np.float32(x[j])
        for i in range(m):
            out[i] += c * AT[j, i]
        j += 1


