def _dot(a, b, n):
    s = 0.0
    for j in range(n):
        s += a[j] * b[j]
    return s


@nb.njit(fastmath=True)
def _chol_solve(L, e, b, y):
    # solve L L^T y = b
    for i in range(e):
        s = b[i]
        for j in range(i):
            s -= L[i, j] * y[j]
        y[i] = s / L[i, i]
    for i in range(e - 1, -1, -1):
        s = y[i]
        for j in range(i + 1, e):
            s -= L[j, i] * y[j]
        y[i] = s / L[i, i]


@nb.njit(fastmath=True)
def _chol_solve2(L, e, b1, b2, y1, y2):
    for i in range(e):
        s1 = b1[i]
        s2 = b2[i]
        for j in range(i):
            l = L[i, j]
            s1 -= l * y1[j]
            s2 -= l * y2[j]
        inv = 1.0 / L[i, i]
        y1[i] = s1 * inv
        y2[i] = s2 * inv
    for i in range(e - 1, -1, -1):
        inv = 1.0 / L[i, i]
        a1 = y1[i] * inv
        a2 = y2[i] * inv
        y1[i] = a1
        y2[i] = a2
        for j in range(i):
            l = L[i, j]
            y1[j] -= l * a1
            y2[j] -= l * a2


@nb.njit(fastmath=True)
def _chol_add(L, e, g, gamma):
    # g: new column G[0:e, e]; returns False if singular
    for i in range(e):
        s = g[i]
        for j in range(i):
            s -= L[i, j] * L[e, j]
        L[e, i] = s / L[i, i]
    s = gamma
    for j in range(e):
        s -= L[e, j] * L[e, j]
    if s <= 1e-10 * gamma:
        return False
    L[e, e] = np.sqrt(s)
    return True


@nb.njit(fastmath=True)
def _chol_del(L, e, p):
    # remove row/col p from e x e factor
    for i in range(p, e - 1):
        for j in range(i + 2):
            L[i, j] = L[i + 1, j]
    for j in range(p, e - 1):
        a = L[j, j]
        b = L[j, j + 1]
        r = np.sqrt(a * a + b * b)
        c = a / r
        s = b / r
        for i in range(j, e - 1):
            u = L[i, j]
            v = L[i, j + 1]
            L[i, j] = c * u + s * v
            L[i, j + 1] = -s * u + c * v
        L[j, j + 1] = 0.0
    for i in range(e):
        L[i, e - 1] = 0.0
        L[e - 1, i] = 0.0


@nb.njit(fastmath=True)
def homotopy2(x0, A, AT, AT32, k, alpha, maxev):
