        for p in range(e):
            bvec[p] = -_dot(A[Elist[p]], aT, d)
        _chol_solve2(L, e, ones, bvec, g1, g2)
        s1 = 0.0
        s2 = 0.0
        for p in range(e):
            s1 += g1[p]
            s2 += g2[p]
        tq = (s2 - (k - nT)) / s1
