        v4 x4r = ir[4*is+v], x4i = ii[4*is+v];
        v4 x5r = ir[5*is+v], x5i = ii[5*is+v];
        v4 x6r = ir[6*is+v], x6i = ii[6*is+v];
        v4 s1r = x1r + x6r, s1i = x1i + x6i, d1r = x1r - x6r, d1i = x1i - x6i;
        v4 s2r = x2r + x5r, s2i = x2i + x5i, d2r = x2r - x5r, d2i = x2i - x5i;
        v4 s3r = x3r + x4r, s3i = x3i + x4i, d3r = x3r - x4r, d3i = x3i - x4i;
        outr[v] = x0r + s1r + s2r + s3r;
        outi[v] = x0i + s1i + s2i + s3i;
        v4 a1r = x0r + C1_*s1r + C2_*s2r + C3_*s3r;
        v4 a1i = x0i + C1_*s1i + C2_*s2i + C3_*s3i;
        v4 b1r = S1_*d1r + S2_*d2r + S3_*d3r;
        v4 b1i = S1_*d1i + S2_*d2i + S3_*d3i;
        v4 a2r = x0r + C2_*s1r + C3_*s2r + C1_*s3r;
        v4 a2i = x0i + C2_*s1i + C3_*s2i + C1_*s3i;
        v4 b2r = S2_*d1r - S3_*d2r - S1_*d3r;
        v4 b2i = S2_*d1i - S3_*d2i - S1_*d3i;
        v4 a3r = x0r + C3_*s1r + C1_*s2r + C2_*s3r;
        v4 a3i = x0i + C3_*s1i + C1_*s2i + C2_*s3i;
        v4 b3r = S3_*d1r - S1_*d2r + S2_*d3r;
        v4 b3i = S3_*d1i - S1_*d2i + S2_*d3i;
        outr[1*os+v] = a1r + b1i; outi[1*os+v] = a1i - b1r;
        outr[6*os+v] = a1r - b1i; outi[6*os+v] = a1i + b1r;
        outr[2*os+v] = a2r + b2i; outi[2*os+v] = a2i - b2r;
        outr[5*os+v] = a2r - b2i; outi[5*os+v] = a2i + b2r;
        outr[3*os+v] = a3r + b3i; outi[3*os+v] = a3i - b3r;
        outr[4*os+v] = a3r - b3i; outi[4*os+v] = a3i + b3r;
    }
}


typedef struct {
    int32_t ginv[N];   /* source index n -> u position p */
    float gsgn[N];     /* sign by source index */
    float ct[23*H1];
    float st[23*H1];
    float twr[49], twi[49];
    int32_t pidx[N];
    float pcs[N], psn[N];
} tables_t;

/* u: element (p, v) at u[p*us + v]; V outputs at Vr[pos*vs + v] */
static void core(const tables_t* T, const v4* u, int us, v4* Vr, v4* Vi, int vs, v4* Ar, v4* Ai, v4* tr, v4* ti) {
    for (int n2 = 0; n2 < N2; n2++) {
        const v4* un = u + n2*N1*us;
        v4 s[23][NV], d[23][NV];
        v4 u0[NV];
        for (int v = 0; v < NV; v++) u0[v] = un[v];
        for (int j = 1; j <= 23; j++) {
            for (int v = 0; v < NV; v++) {
                v4 a = un[j*us+v], b = un[(47-j)*us+v];
                s[j-1][v] = a + b; d[j-1][v] = a - b;
            }
        }
        for (int kb = 0; kb < H1; kb += KB) {
            v4 ar[KB][NV], ai[KB][NV];
            for (int kk = 0; kk < KB; kk++)
                for (int v = 0; v < NV; v++) { ar[kk][v] = u0[v]; ai[kk][v] = (v4){0,0,0,0}; }
            for (int j = 0; j < 23; j++) {
                const float* cj = T->ct + j*H1 + kb;
                const float* sj = T->st + j*H1 + kb;
                for (int kk = 0; kk < KB; kk++) {
                    float c = cj[kk], sn = sj[kk];
                    for (int v = 0; v < NV; v++) {
                        ar[kk][v] += s[j][v] * c;
                        ai[kk][v] += d[j][v] * sn;
                    }
                }
            }
            for (int kk = 0; kk < KB; kk++)
                for (int v = 0; v < NV; v++) {
                    Ar[((kb+kk)*N2 + n2)*NV + v] = ar[kk][v];
                    Ai[((kb+kk)*N2 + n2)*NV + v] = ai[kk][v];
                }
        }
    }
    for (int k1 = 0; k1 < H1; k1++) {
        const v4* xr = Ar + k1*N2*NV;
        const v4* xi = Ai + k1*N2*NV;
        for (int q = 0; q < 7; q++) {
            dft7(xr + q*NV, xi + q*NV, 7*NV, tr + q*7*NV, ti + q*7*NV, NV);
            if (q == 0) continue;
            for (int r = 1; r < 7; r++) {
                float wr = T->twr[q*7+r], wi = T->twi[q*7+r];
                for (int v = 0; v < NV; v++) {
                    v4 a = tr[(q*7+r)*NV+v], b = ti[(q*7+r)*NV+v];
                    tr[(q*7+r)*NV+v] = a*wr - b*wi;
                    ti[(q*7+r)*NV+v] = a*wi + b*wr;
                }
            }
        }
        v4* yr = Vr + k1*N2*vs;
        v4* yi = Vi + k1*N2*vs;
        for (int r = 0; r < 7; r++)
            dft7(tr + r*NV, ti + r*NV, 7*NV, yr + r*vs, yi + r*vs, 7*vs);
    }
}

static void* amalloc(size_t sz) { void* p = NULL; if (posix_memalign(&p, 128, sz)) return NULL; return p; }

static void core_all(const tables_t* T, const v4* u, v4* Vr, v4* Vi, v4* Ar, v4* Ai, v4* tr, v4* ti) {
#ifdef NOCORE
    return;
#endif
    for (int h = 0; h < NBV; h += NV)
        core(T, u + h, NBV, Vr + h, Vi + h, NBV, Ar, Ai, tr, ti);
}

void dst2d(const tables_t* T, const double* X, float* W, float* Y, int nthreads, int mode) {
    const int nblk = (N + LWB - 1) / LWB;
    #pragma omp parallel num_threads(nthreads)
    {
        v4* u  = (v4*)amalloc(sizeof(v4)*N*NBV);
        v4* Vr = (v4*)amalloc(sizeof(v4)*H1*N2*NBV);
        v4* Vi = (v4*)amalloc(sizeof(v4)*H1*N2*NBV);
        v4* Ar = (v4*)amalloc(sizeof(v4)*H1*N2*NV);
        v4* Ai = (v4*)amalloc(sizeof(v4)*H1*N2*NV);
        v4* tr = (v4*)amalloc(sizeof(v4)*49*NV);
        v4* ti = (v4*)amalloc(sizeof(v4)*49*NV);
        float* uf = (float*)u;
        const float* vr = (const float*)Vr; const float* vi = (const float*)Vi;
        if (mode & 1) {
        #pragma omp for schedule(static)
        for (int b = 0; b < nblk; b++) {
            int c0 = b*LWB;
            int nv = N - c0; if (nv > LWB) nv = LWB;
            if (nv == LWB) {
                for (int n = 0; n < N; n++) {
                    const double* row = X + (size_t)n*N + c0;
                    float sg = T->gsgn[n]; float* dst = uf + T->ginv[n]*LWB;
                    for (int l = 0; l < LWB; l++) dst[l] = sg*(float)row[l];
                }
            } else {
                for (int n = 0; n < N; n++) {
                    const double* row = X + (size_t)n*N + c0;
                    float sg = T->gsgn[n]; float* dst = uf + T->ginv[n]*LWB;
                    for (int l = 0; l < LWB; l++) dst[l] = (l < nv) ? sg*(float)row[l] : 0.f;
                }
            }
            core_all(T, u, Vr, Vi, Ar, Ai, tr, ti);
            if (nv == LWB) {
                for (int k = 0; k < N; k++) {
                    int pos = T->pidx[k]; float cs = T->pcs[k], sn = T->psn[k];
                    float* out = W + (size_t)k*N + c0;
                    for (int l = 0; l < LWB; l++) out[l] = cs*vr[pos*LWB+l] + sn*vi[pos*LWB+l];
                }
            } else {
                for (int k = 0; k < N; k++) {
                    int pos = T->pidx[k]; float cs = T->pcs[k], sn = T->psn[k];
                    float* out = W + (size_t)k*N + c0;
                    for (int l = 0; l < nv; l++) out[l] = cs*vr[pos*LWB+l] + sn*vi[pos*LWB+l];
                }
            }
        }
        }
        if (mode & 2) {
        #pragma omp for schedule(static)
        for (int b = 0; b < nblk; b++) {
            int r0 = b*LWB;
            int nv = N - r0; if (nv > LWB) nv = LWB;
            const float* rows[LWB];
            for (int l = 0; l < LWB; l++) rows[l] = W + (size_t)((l < nv) ? r0 + l : r0)*N;
            for (int n = 0; n < N; n++) {
                float sg = T->gsgn[n]; float* dst = uf + T->ginv[n]*LWB;
                for (int l = 0; l < LWB; l++) dst[l] = sg*rows[l][n];
            }
            core_all(T, u, Vr, Vi, Ar, Ai, tr, ti);
            float* orow[LWB];
            for (int l = 0; l < LWB; l++) orow[l] = Y + (size_t)(r0 + l)*N;
            if (nv == LWB) {
                for (int k = 0; k < N; k++) {
                    int pos = T->pidx[k]; float cs = T->pcs[k], sn = T->psn[k];
                    for (int l = 0; l < LWB; l++) orow[l][k] = cs*vr[pos*LWB+l] + sn*vi[pos*LWB+l];
                }
            } else {
                for (int k = 0; k < N; k++) {
                    int pos = T->pidx[k]; float cs = T->pcs[k], sn = T->psn[k];
                    for (int l = 0; l < nv; l++) orow[l][k] = cs*vr[pos*LWB+l] + sn*vi[pos*LWB+l];
                }
            }
        }
        }
        free(u); free(Vr); free(Vi); free(Ar); free(Ai); free(tr); free(ti);
    }
}

